// In-browser search over data/search.json (generated by export_static.py).
// The index text is already normalized by arabic.normalize() in Python;
// normalize() below mirrors it for the query. Keep the two in sync.
(function () {
  "use strict";

  const DIACRITICS = /[ؐ-ًؚ-ٰٟۖ-ۭـ]/g;
  const LETTERS = { "أ": "ا", "إ": "ا", "آ": "ا", "ٱ": "ا", "ى": "ي", "ة": "ه", "ؤ": "و", "ئ": "ي" };
  const TOKEN = /[\p{L}\p{N}_]+/gu;
  const PREFIX = /^(?:[وف]?(?:[بكل]?ال|لل))(?=[\p{L}\p{N}_]{2,})(?!له$)/u;
  const MAX_RESULTS = 100;

  function normalizeTokens(text) {
    const plain = text.replace(DIACRITICS, "").replace(/[أإآٱىةؤئ]/g, (c) => LETTERS[c]);
    return (plain.match(TOKEN) || []).map((t) => t.replace(PREFIX, ""));
  }

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  }

  const $ = (id) => document.getElementById(id);
  const params = new URLSearchParams(location.search);
  const query = (params.get("q") || "").trim();
  const tag = (params.get("tag") || "").trim();

  $("q").value = query;
  $("tag").value = tag;
  $("tag").addEventListener("change", () => $("search-form").submit());
  for (const chip of document.querySelectorAll("#tag-chips .tag")) {
    chip.classList.toggle("active", chip.dataset.tag === tag);
    if (query) chip.href = "?q=" + encodeURIComponent(query) + "&tag=" + encodeURIComponent(chip.dataset.tag);
  }

  if (!query && !tag) return;
  $("books").hidden = true;
  const out = $("results");
  out.innerHTML = '<p class="muted">جارٍ تحميل الفهرس…</p>';

  fetch("data/search.json")
    .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then((index) => render(index))
    .catch((err) => { out.innerHTML = '<p class="muted">تعذّر تحميل الفهرس (' + escapeHtml(String(err)) + ').</p>'; });

  function render(index) {
    const books = new Map(index.books.map((b) => [b.id, b]));
    const chapters = new Map(index.chapters.map((c) => [c.id, c]));
    const inTag = (chapterId) => !tag || chapters.get(chapterId).tags.includes(tag);

    if (!query) {
      const list = index.chapters.filter((c) => c.tags.includes(tag));
      out.innerHTML = "<h2>أبواب موضوع «" + escapeHtml(tag) + "»</h2>" + list.map((c) =>
        '<div class="card"><div class="crumbs">' + escapeHtml(books.get(c.b).title) + "</div>" +
        '<a href="book/' + c.b + ".html#ch" + c.id + '"><strong>' + escapeHtml(c.name) + "</strong></a>" +
        '<span class="muted"> · ' + c.n + " فصل</span></div>").join("");
      return;
    }

    const terms = [...new Set(normalizeTokens(query))];
    if (!terms.length) { out.innerHTML = ""; return; }

    // Count term occurrences per section; a section must contain every term.
    const docs = index.sections.filter((s) => inTag(s.c)).map((s) => {
      const counts = new Map();
      for (const t of s.t.match(TOKEN) || []) if (terms.includes(t)) counts.set(t, (counts.get(t) || 0) + 1);
      const nameTokens = new Set(s.nn.match(TOKEN) || []);
      return { s, counts, nameTokens };
    });
    const hits = docs.filter((d) => terms.every((t) => d.counts.has(t) || d.nameTokens.has(t)));

    // Rank: tf-idf with title matches weighted 5x (like bm25(…, 5.0, 1.0) in search.py).
    const N = index.sections.length;
    const idf = Object.fromEntries(terms.map((t) => [t, Math.log(1 + N / (1 + docs.filter((d) => d.counts.has(t)).length))]));
    for (const d of hits) {
      d.score = terms.reduce((sum, t) =>
        sum + idf[t] * (Math.log(1 + (d.counts.get(t) || 0)) + (d.nameTokens.has(t) ? 5 : 0)), 0);
    }
    hits.sort((a, b) => b.score - a.score);
    const shown = hits.slice(0, MAX_RESULTS);

    const termRe = new RegExp("(?<![\\p{L}\\p{N}_])(" + terms.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|") + ")(?![\\p{L}\\p{N}_])", "gu");
    out.innerHTML =
      "<h2>" + hits.length + " نتيجة" + (hits.length > MAX_RESULTS ? " (أول " + MAX_RESULTS + ")" : "") + "</h2>" +
      (shown.length ? shown.map((d) => {
        const c = chapters.get(d.s.c);
        return '<div class="card"><div class="crumbs">' + escapeHtml(books.get(c.b).title) + " › " + escapeHtml(c.name) + "</div>" +
          '<a href="section/' + d.s.id + '.html"><strong>' + escapeHtml(d.s.name) + "</strong></a>" +
          '<div class="snippet">' + snippet(d.s.t, termRe) + "</div></div>";
      }).join("") : '<p class="muted">لا نتائج. جرّب كلمة أخرى أو صيغة مختلفة (مثلاً «فروض» بدل «فرائض»).</p>');
  }

  function snippet(text, termRe) {
    termRe.lastIndex = 0;
    const m = termRe.exec(text);
    const at = m ? m.index : 0;
    let start = Math.max(0, at - 90), end = Math.min(text.length, at + 160);
    if (start > 0) start = text.indexOf(" ", start) + 1;
    if (end < text.length) end = Math.max(text.lastIndexOf(" ", end), at + 1);
    const piece = escapeHtml(text.slice(start, end).replace(/\n/g, " "));
    return (start > 0 ? "… " : "") + piece.replace(termRe, "<mark>$1</mark>") + (end < text.length ? " …" : "");
  }
})();
